#[derive(Debug, Clone)]
enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

fn eval(e: &Exp, store: &std::collections::HashMap<String, i32>) -> i32 {
    match e {
        Exp::Const(value) => *value,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(left, right) => eval(left, store) + eval(right, store),
        Exp::Mult(left, right) => eval(left, store) * eval(right, store),
    }
}

fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Plus(left, right) => {
            let left_optimized = optimize(*left);
            let right_optimized = optimize(*right);
            match (left_optimized, right_optimized) {
                (Exp::Const(0), r) => r, // neutral element for addition
                (l, Exp::Const(0)) => l, // neutral element for addition
                (Exp::Const(l_val), Exp::Const(r_val)) => {
                    Exp::Const(l_val + r_val) // constant folding
                }
                (l, r) => Exp::Plus(Box::new(l), Box::new(r)),
            }
        }
        Exp::Mult(left, right) => {
            let left_optimized = optimize(*left);
            let right_optimized = optimize(*right);
            match (left_optimized, right_optimized) {
                (Exp::Const(0), _) => Exp::Const(0), // absorbing element
                (_, Exp::Const(0)) => Exp::Const(0), // absorbing element
                (Exp::Const(1), r) => r, // neutral element for multiplication
                (l, Exp::Const(1)) => l, // neutral element for multiplication
                (Exp::Const(l_val), Exp::Const(r_val)) => {
                    Exp::Const(l_val * r_val) // constant folding
                }
                (l, r) => Exp::Mult(Box::new(l), Box::new(r)),
            }
        }
        other => other, // return unchanged for constants and variables
    }
}

// Example usage
fn main() {
    let expr = Exp::Plus(Box::new(Exp::Const(0)), Box::new(Exp::Var("x".to_string())));
    let optimized_expr = optimize(expr.clone());
    
    let mut store = std::collections::HashMap::new();
    store.insert("x".to_string(), 5);
    
    println!("Original evaluation: {}", eval(&expr, &store));
    println!("Optimized evaluation: {}", eval(&optimized_expr, &store));
}